def card(key, difficulty, translations):
    assert set(translations.keys()) == set(LOCALES), f"{key}: {set(translations.keys()) ^ set(LOCALES)}"
    return {"k": key, "d": difficulty, "t": {loc: translations[loc] for loc in LOCALES}}


def t(*args):
    return dict(zip(LOCALES, args))

